{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "TourStep",
    "description": "A single spotlight step. Highlights a target element with a ring drawn as a separate overlay (the target is never restyled) and renders a callout anchored to it (via the core Popover), with a heading, body, optional step progress, and back / next / close controls. Registers with the parent Tour on mount and renders its callout only while active.",
    "props": [
      {
        "name": "targetRef",
        "type": "RefObject<HTMLElement>",
        "description": "Ref to the element this step points at. The callout anchors to it like a Popover trigger; it must be a <button> or [role=\"button\"] element (Popover's anchorRef contract).",
        "required": true
      },
      {
        "name": "heading",
        "type": "ReactNode",
        "description": "Step heading.",
        "required": true
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Step body content."
      },
      {
        "name": "placement",
        "type": "'above' | 'below' | 'start' | 'end'",
        "description": "Which side of the target the callout sits on.",
        "default": "'below'"
      },
      {
        "name": "alignment",
        "type": "'start' | 'center' | 'end'",
        "description": "How the callout aligns along the placement side (e.g. with placement=\"below\": start left-aligns under the target, center centers, end right-aligns).",
        "default": "'start'"
      }
    ],
