    "parentDoc": "Tour",
    "usage": {
      "description": "Use a Tour to introduce a feature or onboard a user through a few key parts of the UI. Compose it from TourStep children, each pointing at an element via targetRef; the Tour advances through them with Next/Back and ends on Done. It is controlled: keep isActive in your own state and persist \"has seen this tour\" yourself (the component only reports dismissal via onDismiss). Built on the existing Popover/Layer anchoring and overlay tokens rather than a bespoke positioning engine.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Keep tours short: a few high-value steps. Long tours get skipped."
        },
        {
          "guidance": true,
          "description": "Persist completion yourself (from onDismiss) so a user does not see the same tour on every visit."
        },
        {
          "guidance": true,
          "description": "Point each step at a stable, visible element; ensure the target is on-screen before its step becomes active."
        },
        {
          "guidance": false,
          "description": "Gate essential, must-see information behind a tour step; users can dismiss it; put critical info inline."
        },
        {
          "guidance": false,
          "description": "Use a tour as a substitute for clear UI; fix confusing interfaces rather than narrating them."
        }
      ]
    },
